def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    tiles = []
    # The figure is an exact tiling by 2x2 squares and L triominoes.
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if square <= cells:
                tiles.append((square, 1))
            for dr, dc, color in ((0, 0, 2), (0, 1, 4), (1, 0, 3), (1, 1, 2)):
                tri = square - {(r + dr, c + dc)}
                if tri <= cells:
                    tiles.append((tri, color))

    @lru_cache(None)
    def cover(remaining):
        remaining = set(remaining)
        if not remaining:
            return ()
        p = min(remaining)
        for shape, color in tiles:
            if p in shape and shape <= remaining:
                rest = cover(tuple(sorted(remaining - shape)))
                if rest is not None:
                    return ((shape, color),) + rest
        return None

    decomposition = cover(tuple(sorted(cells)))
    out = [row[:] for row in grid]
    if decomposition is None:
        return out
    for shape, color in decomposition:
        for r, c in shape:
            out[r][c] = color
    return out

